-- Brand kit part 1, Foundations, locked by Sean 2026-11-11 (playbook ve-brand-kit). Run through ve-once-brand-kit (connector approval hold).

-- step: foundations
insert into public.knowledge_records (slug,title,category,subcategory,body,status,owner,always_load,load_priority,tags,version,change_summary,created_by,updated_by)
select 'canon-ve-brand-kit-foundations','Vegans Explore brand kit, part 1: Foundations (LOCKED)','brand','canonical',$j${"authority": "Sean, 2026-11-11, on the mock /mocks/brand-kit: \"Go with your defaults, merge it, start imagery\"", "reference": "/mocks/brand-kit (12 slides, guided view). Built on canon-ve-look-color-block. Playbook ve-brand-kit.", "colors": {"brand_green": "#2D5C27 white type", "orange": "#F69820 ink type, the one action color", "pink": "#FF9EC4 ink type, the one supporting color (Save, warmth, people); deep pink #C2185B only for pink text on white", "peach": "#FFEBD1 ink type, block only, never a shadow", "bright_green": "#22C55E ink type, votes, highlights, numbers on dark green", "mint": "#E8F5E9 ink type, block only, never a shadow", "mid_green": "#3A9B3E white type only at 19px bold and up (3.5:1), smaller words in ink", "neutrals": "ink #1a1a1a, quiet #5c5c5c, line #e7e7e7, page #ffffff", "measured": "white on orange 2.2, pink 1.9, bright green 2.3: those always take ink"}, "section_colors": {"directory": "brand green (its doors reuse the palette inside)", "events": "orange", "guides": "pink", "communities": "mid green", "daily_pulse": "bright green", "media_podcast": "peach", "passport_membership": "mint (its button stays orange)", "everywhere": "the dark green band with the orange button closes every page"}, "section_color_use": "the page header block, eyebrow, card shadow and the lead of its stripe", "type": "Montserrat only. Display 120/900 (phone 64), headline 72/900 (34), section 40/900 (26), card title 18-23/900, body 14-15/600, small 12.5-13/600, eyebrow 11/900 caps .18em, big number 40/900 with 10px caps label, button 12/900 caps .1em. Headlines letter-spacing -.025em, line height about 1.04. No second font, no italics for emphasis.", "marker": "band from 56% to 92% of the line, 4px corner, box-decoration-break clone; one to three short phrases per headline; headings 26px and up only; green, orange or pink (section color first); on dark green the word turns bright green instead; never peach or mint, never body copy, never a full box.", "stripe": "seven colors in order: brand green (double width), orange, pink, peach, bright green, mint, mid green. Web 8px once per page under search or title; email 6px across the top; social and thumbnails full width along the bottom, about 1.5% of height; video lower thirds a thin stripe under the name plate. Never reordered or recolored. The mosaic (nine tiles) is a corner accent on hero headers, covers and end cards, one per frame.", "cards": "2px ink outline, 14px corner, 46-54px band in the section color, logo on a white square over the band edge linking to the profile, two-row clamp, one action row; shadow solid 6px 6px 0 in the section color (ink for peach and mint), hover lifts 2px to 8px, phones 5px. Doors and feature blocks: solid color, no outline, picture in a white frame.", "buttons": "one orange primary per view (ink type); secondary white with ink outline; vote bright green, dark green when on; save pink when on; on the dark green band: orange primary, white second, outlined white rest. 6px corners, 2px outline, 900 caps, never pills or gradients. Status tags in plain words with a dot. Search and main picker 3px ink outline, fields 2px; dropdowns use our chevron 16px from the edge.", "shadows_corners_spacing": "solid offset shadows only, no blur. Corners 6 controls, 10 pictures, 14 cards, 16 bands. Spacing 6, 10, 16, 22, 40 (desktop edge), 52 (between sections); full width always.", "logo": "see canon-ve-logo v3: portrait v2 on white; inverted on black or dark non-green colors; all-white on brand green and over pictures (soft shadow, never on a face); landscape v1 in the site header only. Clear space = handle height; minimum portrait 64px, landscape 120px."}$j$::jsonb,'active','sar',false,20,array['vegans-explore','brand','brand-kit','foundations','color-block','canon'],1,'Created: Sean locked part 1 of the brand kit with all four defaults (pink A, section map, orange the only action color, stripe everywhere).','logan','logan'
where not exists (select 1 from public.knowledge_records where slug='canon-ve-brand-kit-foundations');

-- step: logo
update public.knowledge_records set version=3, updated_by='logan', updated_at=now(),
 change_summary='v3 (2026-11-11, approved by Sean with brand kit Foundations): the inverted file goes on black or dark colors that are not green; on brand green the green mark disappears, so brand green takes the all-white file.',
 body = jsonb_set(jsonb_set(body,'{files,on_dark_or_color}',$j$"/public/logo-ve-portrait-v2-inverted.svg (green mark, white type): on black or dark colors that are NOT green (the shirt look). Never on brand green #2D5C27, where the mark disappears."$j$::jsonb),'{use}',(body->'use') || $j$["On brand green (the main call to action band, green covers) use the ALL-WHITE logo; the inverted file's green mark vanishes there (found in proof 2026-11-11, brand kit Foundations). On orange or pink use the normal file on a white plate."]$j$::jsonb)
where slug='canon-ve-logo' and status='active' and version=2;
